#' Find used functions and packages
#'
#' This function is primarily exported for developers, and
#' is almost entirely divested from `stanflow`, except for
#' defaults and `{stanflow}` behavior explained later.
#'
#' The scanning is wholly static (tree-sitter parsing), so there are
#' a number of restrictions on what calls are recognized:
#' calls to `library()`, `require()`, `requireNamespace()`,
#' or `use()` are all recognized as attaching a package.
#'
#' The Stan values for `allowed_packages`, `export_index`, and `origin_map`
#' are generated by `data_raw/sysdata.R`.
#'
#' Unqualified function calls are only attributed when a Stan package is
#' attached via `library()` or `require()` in the same file. Attaching
#' `{stanflow}` is hardcoded as attaching its core packages (`bayesplot`, `loo`,
#' `posterior`, `projpred`, `shinystan`). When multiple attached Stan packages
#' export the same unqualified function, attachment order is respected: the
#' most recently attached matching package whose attachment appears before the
#' call is treated as the winner. Known reexports are remapped to their origin
#' packages; missing mappings fall back to the resolved package.
#'
#' @inheritParams stan_cite
#' @param allowed_packages Character vector of package namespaces to attribute
#'   to Stan usage. Defaults to `.stan_pkgs`.
#' @param export_index Named list mapping function names to packages. Defaults
#'   to `.stan_export_index`.
#' @param origin_map Named character vector mapping `pkg::fun` keys to the
#'   origin package. Defaults to `.stan_origin_map`.
#' @param skip_dirs Character vector of directory names to skip when scanning a
#'   directory. Defaults to `.scan_skip_dirs`.
#' @return A list of packages, resolved functions, and ambiguous function calls.
#' @export
#' @examples
#' path <- tempfile(fileext = ".R")
#' writeLines(
#'   c(
#'     "# one messy analysis file",
#'     "library(posterior)",
#'     "requireNamespace(\"brms\")",
#'     "use(\"cmdstanr\", c(\"cmdstan_model\", \"write_stan_json\"))",
#'     "draws <- as_draws(list(mu = rnorm(10)))",
#'     "posterior::rhat(draws)",
#'     "brms::mixture(0.4)",
#'     "cmdstanr::write_stan_json(list(N = 3), \"data.json\")"
#'   ),
#'   path
#' )
#' scan_usage(path, quiet = TRUE)
#' unlink(path)
scan_usage <- function(
  path = ".",
  ignore_unqualified_functions = .stdlib_funs,
  strict = FALSE,
  skip_dirs = .scan_skip_dirs,
  allowed_packages = .stan_pkgs,
  export_index = .stan_export_index,
  origin_map = .stan_origin_map,
  quiet = getOption("stanflow.quiet", FALSE)
) {
  local_cli_quiet(quiet)

  paths <- normalizePath(path, winslash = "/", mustWork = TRUE)
  dir_flags <- dir.exists(paths)

  files <- if (length(paths) == 1L && dir_flags) {
    dir_path <- paths[[1L]]
    cli::cli_alert_info("Searching directory {.path {dir_path}}")
    .scan_dir_files(dir_path, skip_dirs)
  } else {
    if (any(dir_flags)) {
      cli::cli_abort(c(
        "{.arg path} must be a single directory or a vector of files.",
        "x" = "Mixed directories and files or multiple directories are not supported."
      ))
    }
    paths |>
      (\(paths) {
        lapply(
          paths,
          \(file_path) cli::cli_alert_info("Searching {.path {file_path}}")
        )
        paths
      })()
  }

  if (!length(files)) {
    cli::cli_abort(c(
      "No files found.",
      "i" = "Check the {.arg path} and {.arg skip_dirs} arguments."
    ))
  }

  hits <- unique(files) |>
    lapply(
      \(file) {
        file |>
          .extract_code() |>
          .scan_tokens(
            ignore_unqualified_functions = ignore_unqualified_functions,
            allowed_packages = allowed_packages,
            export_index = export_index,
            origin_map = origin_map,
            file_path = file
          )
      }
    )

  ambiguous <- .collect_unique(hits, "ambiguous")
  if (length(ambiguous)) {
    msg <- c(
      "Cannot reliably detect which packages some functions are from.",
      "x" = paste0(
        "Ambiguous functions: ",
        paste0("{.fun ", ambiguous, "}", collapse = ", ")
      ),
      "i" = "Please namespace them ({.code pkg::function()}) and rerun or set {.code strict = FALSE}."
    )

    if (strict) cli::cli_abort(msg) else cli::cli_warn(msg)
  }

  structure(
    list(
      packages = .collect_unique(hits, "pkgs"),
      functions = .collect_unique(hits, "keys"),
      ambiguous = ambiguous
    ),
    class = "scan_usage"
  )
}

.scan_skip_regex <- function(skip_dirs) {
  escaped <- vapply(
    skip_dirs,
    \(x) gsub("([][{}()+*^$|\\\\.?])", "\\\\\\1", x),
    character(1)
  )
  paste0("(^|/)(?:", paste(escaped, collapse = "|"), ")(/|$)")
}

.scan_dir_walk <- function(path, skip_dirs, file_cb) {
  entries <- list.files(
    path,
    all.files = TRUE,
    full.names = TRUE,
    no.. = TRUE
  )
  if (!length(entries)) {
    return(invisible(NULL))
  }

  is_dir <- dir.exists(entries)

  if (any(is_dir)) {
    dirs <- entries[is_dir]
    if (length(skip_dirs)) {
      keep <- is.na(fastmatch::fmatch(basename(dirs), skip_dirs))
      dirs <- dirs[keep]
    }
    if (length(dirs)) {
      for (dir in dirs) {
        .scan_dir_walk(dir, skip_dirs, file_cb)
      }
    }
  }

  if (!all(is_dir)) {
    file_cb(entries[!is_dir])
  }

  invisible(NULL)
}

.scan_dir_files <- function(dir_path, skip_dirs) {
  dir_path <- normalizePath(dir_path, winslash = "/", mustWork = TRUE)
  files <- character()
  n <- 0L

  add_code_files <- function(paths) {
    code_files <- paths[grepl("\\.(R|Rmd|Qmd)$", paths, ignore.case = TRUE)]
    if (!length(code_files)) {
      return(invisible(NULL))
    }

    idx <- seq.int(n + 1L, n + length(code_files))
    files[idx] <<- code_files
    n <<- idx[length(idx)]

    invisible(NULL)
  }

  .scan_dir_walk(dir_path, skip_dirs, add_code_files)
  normalizePath(files, winslash = "/", mustWork = FALSE)
}

.collect_unique <- function(hits, field) {
  hits |>
    lapply(`[[`, field) |>
    unlist(use.names = FALSE) |>
    unique() |>
    sort()
}

.extract_code <- function(file) {
  ext <- file |>
    sub(".*\\.", "", x = _) |>
    tolower()

  if (!ext %in% c("r", "rmd", "qmd")) {
    cli::cli_abort(c(
      "Unsupported file extension: {.val {ext}}.",
      "i" = "Supported extensions are {.file .R}, {.file .Rmd}, and {.file .qmd}."
    ))
  }

  if (ext == "r") {
    return(paste(readLines(file, warn = FALSE), collapse = "\n"))
  }
  if (!requireNamespace("knitr", quietly = TRUE)) {
    cli::cli_abort(c(
      "Package {.pkg knitr} is required to parse R Markdown ({.file .Rmd}) or Quarto ({.file .qmd}) files.",
      "i" = "Please install it with {.code install.packages('knitr')}."
    ))
  }

  tmp <- withr::local_tempfile(fileext = ".R")
  knitr::purl(file, tmp, quiet = TRUE, documentation = 0)

  paste(readLines(tmp, warn = FALSE), collapse = "\n")
}

.scan_tokens <- function(
  code,
  ignore_unqualified_functions,
  allowed_packages = .stan_pkgs,
  export_index = .stan_export_index,
  origin_map = .stan_origin_map,
  file_path = NULL
) {
  empty <- list(pkgs = character(), keys = character(), ambiguous = character())
  if (!nzchar(code)) {
    return(empty)
  }

  scan_state <- .scan_treesitter()
  tree <- treesitter::parser_parse(scan_state$parser, code)
  root <- treesitter::tree_root_node(tree)

  if (treesitter::node_has_error(root)) {
    path_label <- if (!is.null(file_path) && nzchar(file_path)) {
      file_path
    } else {
      "<unknown file>"
    }
    msg <- c(
      "Failed to parse {.path {path_label}}.",
      "x" = "Syntax error in file."
    )
    cli::cli_warn(msg)
    return(empty)
  }

  export_names <- names(export_index)
  if (is.null(export_names)) {
    export_names <- character()
  }

  lib_data <- .scan_attached_packages(
    root = root,
    scan_state = scan_state,
    allowed_packages = allowed_packages
  )

  ns_hits <- .scan_namespaced_hits(
    root = root,
    scan_state = scan_state,
    allowed_packages = allowed_packages
  )

  unqual <- .scan_unqualified_candidates(
    root = root,
    scan_state = scan_state,
    export_names = export_names,
    ignore_unqualified_functions = ignore_unqualified_functions
  )

  resolved <- .resolve_candidates(
    unqual = unqual,
    lib_data,
    allowed_packages,
    export_index,
    origin_map
  )

  list(
    pkgs = c(
      if (is.null(lib_data)) character() else lib_data$pkg,
      ns_hits$pkgs,
      resolved$pkgs
    ),
    keys = c(ns_hits$keys, resolved$keys),
    ambiguous = resolved$ambiguous
  )
}

.scan_treesitter <- local({
  bundle <- NULL

  function() {
    if (!is.null(bundle)) {
      return(bundle)
    }

    language <- treesitter.r::language()

    # Compile the R grammar queries once; scan_usage() reuses them for every file.
    bundle <<- list(
      parser = treesitter::parser(language),
      attach_calls = treesitter::query(
        language,
        .scan_query_sources$attach_calls
      ),
      use_calls = treesitter::query(
        language,
        .scan_query_sources$use_calls
      ),
      plain_calls = treesitter::query(
        language,
        .scan_query_sources$plain_calls
      ),
      namespace_uses = treesitter::query(
        language,
        .scan_query_sources$namespace_uses
      ),
      member_calls = treesitter::query(
        language,
        .scan_query_sources$member_calls
      )
    )

    bundle
  }
})

.scan_attached_packages <- function(root, scan_state, allowed_packages) {
  hits <- .scan_capture_rows(
    root,
    scan_state$attach_calls,
    "call",
    c("call", "head", "args")
  )
  if (!length(hits)) {
    return(NULL)
  }

  pkgs <- character()
  visit_idx <- integer()
  is_attach <- logical()

  for (hit in hits) {
    head_name <- .scan_node_name(hit$head)
    pkg <- .scan_pkg_arg(hit$args)
    if (is.null(head_name) || is.null(pkg)) {
      next
    }

    idx <- as.integer(treesitter::node_start_byte(hit$call))
    attached <- head_name != "requireNamespace"

    if (!is.na(fastmatch::fmatch(pkg, allowed_packages))) {
      pkgs <- c(pkgs, pkg)
      visit_idx <- c(visit_idx, idx)
      is_attach <- c(is_attach, attached)
    }

    if (pkg == "stanflow" && attached) {
      core_pkgs <- core
      if (length(core_pkgs)) {
        core_pkgs <- core_pkgs[
          !is.na(fastmatch::fmatch(core_pkgs, allowed_packages))
        ]
      }
      if (length(core_pkgs)) {
        pkgs <- c(pkgs, core_pkgs)
        visit_idx <- c(visit_idx, rep.int(idx, length(core_pkgs)))
        is_attach <- c(is_attach, rep.int(TRUE, length(core_pkgs)))
      }
    }
  }

  if (!length(pkgs)) {
    return(NULL)
  }

  data.frame(
    visit_idx = visit_idx,
    pkg = pkgs,
    is_attach = is_attach,
    stringsAsFactors = FALSE
  )
}

.scan_namespaced_hits <- function(root, scan_state, allowed_packages) {
  use_hits <- .scan_use_hits(root, scan_state, allowed_packages)
  namespace_hits <- .scan_namespace_hits(root, scan_state, allowed_packages)

  list(
    pkgs = c(use_hits$pkgs, namespace_hits$pkgs),
    keys = c(use_hits$keys, namespace_hits$keys)
  )
}

.scan_use_hits <- function(root, scan_state, allowed_packages) {
  hits <- .scan_capture_rows(
    root,
    scan_state$use_calls,
    "call",
    c("args")
  )
  if (!length(hits)) {
    return(list(pkgs = character(), keys = character()))
  }

  pkgs <- character()
  keys <- character()

  for (hit in hits) {
    args <- .scan_argument_data(hit$args)
    if (!length(args) || !is.null(args[[1L]]$name)) {
      next
    }

    pkg <- .scan_node_name(args[[1L]]$value)
    if (is.null(pkg) || is.na(fastmatch::fmatch(pkg, allowed_packages))) {
      next
    }

    pkgs <- c(pkgs, pkg)
    funs <- if (length(args) >= 2L && is.null(args[[2L]]$name)) {
      .scan_use_funs(args[[2L]]$value)
    } else {
      character()
    }
    if (length(funs)) {
      keys <- c(keys, paste0(pkg, "::", funs))
    }
  }

  list(pkgs = pkgs, keys = keys)
}

.scan_namespace_hits <- function(root, scan_state, allowed_packages) {
  hits <- .scan_capture_rows(
    root,
    scan_state$namespace_uses,
    "ns",
    c("pkg", "fun")
  )
  if (!length(hits)) {
    return(list(pkgs = character(), keys = character()))
  }

  pkgs <- character()
  keys <- character()

  for (hit in hits) {
    pkg <- .scan_node_name(hit$pkg)
    fun <- .scan_node_name(hit$fun)
    if (
      is.null(pkg) ||
        is.null(fun) ||
        is.na(fastmatch::fmatch(pkg, allowed_packages))
    ) {
      next
    }

    pkgs <- c(pkgs, pkg)
    keys <- c(keys, paste0(pkg, "::", fun))
  }

  list(pkgs = pkgs, keys = keys)
}

.scan_unqualified_candidates <- function(
  root,
  scan_state,
  export_names,
  ignore_unqualified_functions
) {
  plain <- .scan_plain_candidates(
    root,
    scan_state,
    export_names,
    ignore_unqualified_functions
  )
  member <- .scan_member_candidates(root, scan_state, export_names)

  list(
    funs = c(plain$funs, member$funs),
    idx = c(plain$idx, member$idx)
  )
}

.scan_plain_candidates <- function(
  root,
  scan_state,
  export_names,
  ignore_unqualified_functions
) {
  hits <- .scan_capture_rows(
    root,
    scan_state$plain_calls,
    "call",
    c("call", "head")
  )
  if (!length(hits)) {
    return(list(funs = character(), idx = integer()))
  }

  funs <- character()
  idx <- integer()

  for (hit in hits) {
    head_name <- .scan_node_name(hit$head)
    if (
      is.null(head_name) ||
        !is.na(fastmatch::fmatch(head_name, .scan_special_heads)) ||
        is.na(fastmatch::fmatch(head_name, export_names)) ||
        !is.na(fastmatch::fmatch(head_name, ignore_unqualified_functions))
    ) {
      next
    }

    funs <- c(funs, head_name)
    idx <- c(idx, as.integer(treesitter::node_start_byte(hit$call)))
  }

  list(funs = funs, idx = idx)
}

.scan_member_candidates <- function(root, scan_state, export_names) {
  hits <- .scan_capture_rows(
    root,
    scan_state$member_calls,
    "call",
    c("call", "member")
  )
  if (!length(hits)) {
    return(list(funs = character(), idx = integer()))
  }

  funs <- character()
  idx <- integer()

  for (hit in hits) {
    member_fun <- .scan_node_name(hit$member)
    if (
      is.null(member_fun) ||
        is.na(fastmatch::fmatch(member_fun, export_names))
    ) {
      next
    }

    funs <- c(funs, member_fun)
    idx <- c(idx, as.integer(treesitter::node_start_byte(hit$call)))
  }

  list(funs = funs, idx = idx)
}

.scan_capture_rows <- function(root, query, order_capture, fields) {
  matches <- .scan_sort_matches(
    treesitter::query_matches(query, root),
    order_capture
  )
  if (!length(matches)) {
    return(list())
  }

  lapply(
    matches,
    \(match) {
      captures <- lapply(fields, \(field) .scan_match_node(match, field))
      names(captures) <- fields
      captures
    }
  )
}

.scan_match_node <- function(match, name) {
  idx <- fastmatch::fmatch(name, match$name)
  if (is.na(idx)) {
    return(NULL)
  }

  match$node[[idx]]
}

.scan_sort_matches <- function(matches, capture_name) {
  matches <- unlist(matches, recursive = FALSE, use.names = FALSE)
  if (!length(matches)) {
    return(list())
  }

  ord <- order(
    vapply(
      matches,
      \(match) {
        node <- .scan_match_node(match, capture_name)
        if (is.null(node)) {
          return(Inf)
        }
        treesitter::node_start_byte(node)
      },
      numeric(1)
    ),
    seq_along(matches)
  )

  matches[ord]
}

.scan_node_name <- function(node) {
  if (is.null(node)) {
    return(NULL)
  }

  node_type <- treesitter::node_type(node)
  if (node_type == "identifier") {
    return(.scan_identifier_name(node))
  }
  if (node_type == "string") {
    return(.scan_string_name(node))
  }

  NULL
}

.scan_identifier_name <- function(node) {
  text <- treesitter::node_text(node)
  n <- nchar(text, type = "chars")

  if (
    n >= 2L &&
      startsWith(text, "`") &&
      substr(text, n, n) == "`"
  ) {
    return(substr(text, 2L, n - 1L))
  }

  text
}

.scan_string_name <- function(node) {
  content <- treesitter::node_child_by_field_name(node, "content")
  if (is.null(content)) {
    return("")
  }

  treesitter::node_text(content)
}

.scan_argument_data <- function(args_node) {
  if (is.null(args_node)) {
    return(list())
  }

  arg_nodes <- treesitter::node_named_children(args_node)
  if (!length(arg_nodes)) {
    return(list())
  }
  arg_nodes <- arg_nodes[
    vapply(arg_nodes, treesitter::node_type, character(1)) == "argument"
  ]
  if (!length(arg_nodes)) {
    return(list())
  }

  lapply(
    arg_nodes,
    \(arg_node) {
      list(
        name = .scan_node_name(
          treesitter::node_child_by_field_name(arg_node, "name")
        ),
        value = treesitter::node_child_by_field_name(arg_node, "value")
      )
    }
  )
}

.scan_pkg_arg_index <- function(args) {
  if (!length(args)) {
    return(NA_integer_)
  }

  arg_names <- vapply(
    args,
    \(arg) {
      if (is.null(arg$name)) NA_character_ else arg$name
    },
    character(1)
  )

  for (arg_name in .scan_pkg_arg_names) {
    idx <- fastmatch::fmatch(arg_name, arg_names)
    if (!is.na(idx)) {
      return(idx)
    }
  }

  1L
}

.scan_pkg_arg <- function(args_node) {
  args <- .scan_argument_data(args_node)
  if (!length(args)) {
    return(NULL)
  }

  idx <- .scan_pkg_arg_index(args)
  if (is.na(idx) || idx > length(args)) {
    return(NULL)
  }

  .scan_node_name(args[[idx]]$value)
}

.scan_use_funs <- function(node) {
  if (is.null(node)) {
    return(character())
  }

  lit <- .scan_node_name(node)
  if (!is.null(lit)) {
    return(lit)
  }
  if (treesitter::node_type(node) != "call") {
    return(character())
  }

  head_name <- .scan_node_name(
    treesitter::node_child_by_field_name(node, "function")
  )
  if (is.null(head_name) || head_name != "c") {
    return(character())
  }

  args <- .scan_argument_data(
    treesitter::node_child_by_field_name(node, "arguments")
  )
  if (!length(args)) {
    return(character())
  }

  out <- lapply(
    args,
    \(arg) {
      if (!is.null(arg$name)) {
        return(character())
      }
      fun <- .scan_node_name(arg$value)
      if (is.null(fun)) character() else fun
    }
  )
  funs <- unlist(out, use.names = FALSE)
  if (!length(funs)) {
    return(character())
  }

  funs[nzchar(funs)]
}

.origin_pkg <- function(
  pkg,
  fun,
  origin_map = .stan_origin_map
) {
  origin <- unname(origin_map[paste0(pkg, "::", fun)])
  if (is.na(origin)) pkg else origin
}

.resolve_origin_pkg <- function(
  pkg,
  fun,
  origin_map = .stan_origin_map,
  allowed_packages = .stan_pkgs
) {
  origin <- .origin_pkg(pkg, fun, origin_map)
  if (is.na(fastmatch::fmatch(origin, allowed_packages))) pkg else origin
}

.resolve_candidates <- function(
  unqual,
  lib_data,
  allowed_packages = .stan_pkgs,
  export_index = .stan_export_index,
  origin_map = .stan_origin_map
) {
  empty <- list(pkgs = character(), keys = character(), ambiguous = character())
  if (!length(unqual$funs) || !length(allowed_packages)) {
    return(empty)
  }

  attached_pkgs <- character()
  attached_visit_idx <- integer()
  if (!is.null(lib_data) && any(lib_data$is_attach)) {
    attached_pkgs <- lib_data$pkg[lib_data$is_attach]
    attached_visit_idx <- lib_data$visit_idx[lib_data$is_attach]
  }
  if (!length(attached_pkgs)) {
    return(empty)
  }

  if (length(attached_visit_idx) > 1L) {
    ord <- order(attached_visit_idx, seq_along(attached_visit_idx))
    attached_pkgs <- attached_pkgs[ord]
    attached_visit_idx <- attached_visit_idx[ord]
  }

  unique_funs <- unique(unqual$funs)
  meta_by_fun <- setNames(
    lapply(unique_funs, function(fun) {
      providers <- export_index[[fun]]
      if (is.null(providers) || !length(providers)) {
        return(NULL)
      }

      providers <- providers[
        !is.na(fastmatch::fmatch(providers, allowed_packages)) &
          !is.na(fastmatch::fmatch(providers, attached_pkgs))
      ]
      if (!length(providers)) {
        return(NULL)
      }

      origins <- vapply(
        providers,
        .origin_pkg,
        character(1),
        fun = fun,
        origin_map = origin_map
      )
      origins <- origins[!is.na(fastmatch::fmatch(origins, allowed_packages))]
      if (!length(origins)) {
        return(NULL)
      }

      list(
        providers = providers,
        unique_origins = unique(origins)
      )
    }),
    unique_funs
  )

  has_meta <- !vapply(meta_by_fun[unqual$funs], is.null, logical(1))
  if (!any(has_meta)) {
    return(empty)
  }

  idx <- unqual$idx[has_meta]
  funs <- unqual$funs[has_meta]
  if (length(idx) > 1L) {
    ord <- order(idx, seq_along(idx))
    idx <- idx[ord]
    funs <- funs[ord]
  }

  intervals <- findInterval(idx, attached_visit_idx)
  resolved_pkgs <- character(length(idx))
  resolved <- logical(length(idx))

  for (i in seq_along(idx)) {
    meta <- meta_by_fun[[funs[[i]]]]
    if (length(meta$unique_origins) == 1L) {
      resolved_pkgs[[i]] <- meta$unique_origins[[1L]]
      resolved[[i]] <- TRUE
      next
    }

    k <- intervals[[i]]
    if (k == 0L) {
      next
    }

    attached_before <- attached_pkgs[seq_len(k)]
    matches <- fastmatch::fmatch(meta$providers, attached_before)
    if (all(is.na(matches))) {
      next
    }

    pkg <- meta$providers[[which.max(ifelse(is.na(matches), -1L, matches))]]
    resolved_pkgs[[i]] <- .resolve_origin_pkg(
      pkg,
      funs[[i]],
      origin_map,
      allowed_packages
    )
    resolved[[i]] <- TRUE
  }

  list(
    pkgs = resolved_pkgs[resolved],
    keys = if (any(resolved)) {
      paste0(resolved_pkgs[resolved], "::", funs[resolved])
    } else {
      character()
    },
    ambiguous = if (all(resolved)) {
      character()
    } else {
      sort(unique(funs[!resolved]))
    }
  )
}

